def bounded(p,cap,sha):
 s=p.lstat();assert stat.S_ISREG(s.st_mode) and not p.is_symlink() and s.st_size<=cap
 fd=os.open(p,os.O_RDONLY|os.O_CLOEXEC|os.O_NOFOLLOW)
 try:
  opened=os.fstat(fd);assert (opened.st_dev,opened.st_ino,opened.st_size,opened.st_mtime_ns)==(s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns)
  chunks=[];total=0
  while total<=cap:
   block=os.read(fd,min(65536,cap+1-total))
   if not block:break
   chunks.append(block);total+=len(block)
  t=os.fstat(fd)
 finally:os.close(fd)
 b=b''.join(chunks);after=p.lstat();assert len(b)<=cap and (s.st_dev,s.st_ino,s.st_size,s.st_mtime_ns)==(t.st_dev,t.st_ino,t.st_size,t.st_mtime_ns)==(after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns) and hashlib.sha256(b).hexdigest()==sha
 return b
